<?php
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/koneksi.php';require_admin();$pageTitle='Monitoring Siswa';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='delete'){$pdo->prepare("DELETE FROM monitoring WHERE id=?")->execute([$id]);flash('success','Data monitoring dihapus.');redirect('monitoring.php');}
 $sid=(int)($_POST['siswa_id']??0);$tanggal=$_POST['tanggal']??'';$catatan=trim($_POST['catatan']??'');$nilai=$_POST['nilai']??'';$rekomendasi=trim($_POST['rekomendasi']??'');
 if(!$sid||!$tanggal||$catatan===''||$nilai===''||!is_numeric($nilai)||$nilai<0||$nilai>100)$errors[]='Siswa, tanggal, catatan, dan nilai 0–100 wajib diisi.';
 if(!$errors){if($a==='create')$q=$pdo->prepare("INSERT INTO monitoring(siswa_id,tanggal,catatan,nilai,rekomendasi) VALUES(?,?,?,?,?)");else $q=$pdo->prepare("UPDATE monitoring SET siswa_id=?,tanggal=?,catatan=?,nilai=?,rekomendasi=? WHERE id=?");$a==='create'?$q->execute([$sid,$tanggal,$catatan,$nilai,$rekomendasi]):$q->execute([$sid,$tanggal,$catatan,$nilai,$rekomendasi,$id]);flash('success','Monitoring disimpan.');redirect('monitoring.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM monitoring WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$students=$pdo->query("SELECT id,nama FROM siswa ORDER BY nama")->fetchAll();$search=trim($_GET['q']??'');$q=$pdo->prepare("SELECT m.*,s.nama FROM monitoring m JOIN siswa s ON s.id=m.siswa_id WHERE s.nama LIKE ? ORDER BY m.tanggal DESC");$q->execute(["%$search%"]);$rows=$q->fetchAll();include __DIR__.'/../partials/header.php';?>
<div class="page-head"><div><h1>Monitoring PKL</h1><div class="muted">Penilaian dan catatan dari guru pembimbing.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3><?=$edit?'Edit Monitoring':'Tambah Monitoring'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><div class="field"><label>Siswa *</label><select name="siswa_id" required><option value="">Pilih siswa</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=($edit['siswa_id']??'')==$s['id']?'selected':''?>><?=e($s['nama'])?></option><?php endforeach;?></select></div><div class="field"><label>Tanggal monitoring *</label><input type="date" name="tanggal" required value="<?=e($edit['tanggal']??date('Y-m-d'))?>"></div><div class="field"><label>Nilai (0–100) *</label><input type="number" min="0" max="100" name="nilai" required value="<?=e($edit['nilai']??'')?>"></div><div class="field"><label>Rekomendasi</label><input name="rekomendasi" value="<?=e($edit['rekomendasi']??'')?>"></div><div class="field full"><label>Catatan monitoring *</label><textarea name="catatan" required><?=e($edit['catatan']??'')?></textarea></div></div><div class="form-actions"><button class="btn">Simpan Monitoring</button><?php if($edit):?><a class="btn secondary" href="monitoring.php">Batal</a><?php endif;?></div></form></div>
<div class="card"><form class="filters"><input name="q" value="<?=e($search)?>" placeholder="Cari nama siswa"><button class="btn">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Siswa</th><th>Catatan</th><th>Nilai</th><th>Rekomendasi</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['catatan'])?></td><td><b><?=e($r['nilai'])?></b></td><td><?=e($r['rekomendasi'])?></td><td><div class="actions"><a class="btn secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Hapus catatan monitoring?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada data monitoring.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../partials/footer.php';?>
